   150→// ── localStorage 서명 (djb2, character.ts 패턴과 동일) ──────────────────────
   151→
   152→const OWNED_WP_KEY     = 'ownedWallpapers';
   153→const OWNED_WP_SIG_KEY = 'ownedWallpapersSig';
   154→const SELECTED_WP_KEY  = 'selectedWallpaper';
   155→const _WP_SALT         = 'ddong-wp-\u0076\u0031';
   156→
   157→function _signWpList(list: string[]): string {
   158→  const str = [...list].sort().join(',') + _WP_SALT;
   159→  let h = 5381;
   160→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
   161→  return h.toString(36);
   162→}
   163→
   164→function _saveOwnedWp(list: string[]): void {
   165→  localStorage.setItem(OWNED_WP_KEY, JSON.stringify(list));
   166→  localStorage.setItem(OWNED_WP_SIG_KEY, _signWpList(list));
   167→}
   168→
   169→/** 보유 배경화면 목록 반환. 서명 불일치 시 변조로 판단하여 빈 배열로 초기화. */
   170→export function getOwnedWallpapers(): string[] {
   171→  try {
   172→    const raw = localStorage.getItem(OWNED_WP_KEY);
   173→    const sig = localStorage.getItem(OWNED_WP_SIG_KEY);
   174→    const list: string[] = raw ? JSON.parse(raw) : [];
   175→
   176→    if (sig === null) {
   177→      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰 후 서명 최초 발급
   178→      _saveOwnedWp(list);
   179→    } else if (sig !== _signWpList(list)) {
   180→      // 서명 불일치 → 변조로 판단, 빈 배열로 초기화
   181→      _saveOwnedWp([]);
   182→      list.length = 0;
   183→    }
   184→
   185→    // 기본 배경은 항상 보유 (서명 저장 데이터에는 포함 안 됨, 읽기 시점에만 병합)
   186→    for (const id of DEFAULT_WP_IDS) {
   187→      if (!list.includes(id)) list.push(id);
   188→    }
   189→    return list;
   190→  } catch (e) {
   191→    console.error('[getOwnedWallpapers] JSON 파싱 실패:', e);
   192→    return [...DEFAULT_WP_IDS];
   193→  }
   194→}
   195→
   196→/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
   197→export function setOwnedWallpapers(list: string[]): void {
   198→  _saveOwnedWp(list);
   199→}
   200→
   201→/** 배경화면을 보유 목록에 추가 (가챠 완료 직후 호출) */
   202→export function addOwnedWallpaper(id: string): void {
   203→  const owned = getOwnedWallpapers();
   204→  if (!owned.includes(id)) {
   205→    owned.push(id);
   206→    _saveOwnedWp(owned);
   207→  }
   208→}
   209→
   210→/** 선택된 배경화면 ID 반환. 없으면 null (기본 배경 사용). */
   211→export function getSelectedWallpaper(): string | null {
   212→  return localStorage.getItem(SELECTED_WP_KEY);
   213→}
   214→
   215→/** 배경화면 선택 저장. null 전달 시 선택 해제. */
   216→export function setSelectedWallpaper(id: string | null): void {
   217→  if (id === null) {
   218→    localStorage.removeItem(SELECTED_WP_KEY);
   219→  } else {
   220→    localStorage.setItem(SELECTED_WP_KEY, id);
   221→  }
   222→}
   223→
   224→/**
   225→ * 보유 목록과 교차 검증하여 안전한 배경화면 ID 반환.
   226→ * 미보유 배경이 선택되어 있으면 null로 강제 초기화 (변조 방지).
   227→ */
   228→export function getSafeSelectedWallpaper(): string | null {
   229→  const selected = getSelectedWallpaper();
   230→  if (!selected) return null;
   231→  const owned = getOwnedWallpapers();
   232→  if (owned.includes(selected)) return selected;
   233→  // 변조 감지 → null로 강제 초기화
   234→  setSelectedWallpaper(null);
   235→  return null;
   236→}
   237→
   238→/** 배경화면 정의 조회. 없으면 undefined. */
   239→export function getWallpaperDef(id: string): BackgroundDef | undefined {
   240→  return WALLPAPERS.find(w => w.id === id);
   241→}
