   156→
   157→function _signWpList(list: string[]): string {
   158→  const str = [...list].sort().join(',') + _WP_SALT;
   159→  let h = 5381;
   160→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
   161→  return h.toString(36);
   162→}
   163→
   164→function _saveOwnedWp(list: string[]): void {
   165→  localStorage.setItem(OWNED_WP_KEY, JSON.stringify(list));
   166→  localStorage.setItem(OWNED_WP_SIG_KEY, _signWpList(list));
   167→}
