   170→export function getOwnedWallpapers(): string[] {
   171→  try {
   172→    const raw = localStorage.getItem(OWNED_WP_KEY);
   173→    const sig = localStorage.getItem(OWNED_WP_SIG_KEY);
   174→    const list: string[] = raw ? JSON.parse(raw) : [];
   175→
   176→    if (sig === null) {
   177→      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰 후 서명 최초 발급
   178→      _saveOwnedWp(list);
   179→    } else if (sig !== _signWpList(list)) {
   180→      // 서명 불일치 → 변조로 판단, 빈 배열로 초기화
   181→      _saveOwnedWp([]);
   182→      list.length = 0;
   183→    }
   184→
   185→    // 기본 배경은 항상 보유 (서명 저장 데이터에는 포함 안 됨, 읽기 시점에만 병합)
   186→    for (const id of DEFAULT_WP_IDS) {
   187→      if (!list.includes(id)) list.push(id);
   188→    }
   189→    return list;
   190→  } catch (e) {
   191→    console.error('[getOwnedWallpapers] JSON 파싱 실패:', e);
   192→    return [...DEFAULT_WP_IDS];
   193→  }
