   210→/** 선택된 배경화면 ID 반환. 없으면 null (기본 배경 사용). */
   211→export function getSelectedWallpaper(): string | null {
   212→  return localStorage.getItem(SELECTED_WP_KEY);
   213→}
   214→
   215→/** 배경화면 선택 저장. null 전달 시 선택 해제. */
   216→export function setSelectedWallpaper(id: string | null): void {
   217→  if (id === null) {
   218→    localStorage.removeItem(SELECTED_WP_KEY);
