    10→// 뽑기당 드롭율 3.5% → 종당 실효 확률 0.35% (캐릭터 UR과 동일 수준)
    11→const WP_DROP_CHANCE = 0.035; // 슬롯당 3.5% → 종당 실효 확률 약 1.17%
    12→const WP_POOL = [
    13→  { id: 'wp_hanok'     },
