    19→function pullWallpaper(): { id: string } {
    20→  return WP_POOL[Math.floor(Math.random() * WP_POOL.length)];
    21→}
    22→
    23→// ── 뽑기 풀 정의 ────────────────────────────────────────────────────────
    24→// R 80% (10종 균등 배분), SR 19.3% (6종 균등 배분), UR 0.7% (2종 균등 배분)
    25→const SR_W  = 19.3 / 6;   // ≈ 3.217%
    26→const POOL = [
    27→  // ── R등급 ──
    28→  { id: 'log',     grade: 'R',  weight: 8 },
    29→  { id: 'swap',    grade: 'R',  weight: 8 },
    30→  { id: 'sum',     grade: 'R',  weight: 8 },
    31→  { id: 'fork',    grade: 'R',  weight: 8 },
    32→  { id: 'seed',    grade: 'R',  weight: 8 },
    33→  { id: 'session', grade: 'R',  weight: 8 },
    34→  { id: 'branch',  grade: 'R',  weight: 8 },
    35→  { id: 'hook',    grade: 'R',  weight: 8 },
    36→  { id: 'socket',  grade: 'R',  weight: 8 },
    37→  { id: 'index',   grade: 'R',  weight: 8 },
    38→  // ── SR등급 ──
    39→  { id: 'hacker',   grade: 'SR', weight: SR_W },
    40→  { id: 'miner',    grade: 'SR', weight: SR_W },
    41→  { id: 'maehwa',   grade: 'SR', weight: SR_W },
    42→  { id: 'archieve', grade: 'SR', weight: SR_W },
