   182→    const TAB_W = 160;
   183→    const TAB_H = 30;
   184→
   185→    this.charTabBtnBg = this.add.rectangle(110, TAB_Y, TAB_W, TAB_H, 0x1144bb)
   186→      .setStrokeStyle(1.5, 0x4488ff)
   187→      .setInteractive({ useHandCursor: true });
   188→    this.charTabLabel = this.add.text(110, TAB_Y, '캐릭터', {
   189→      fontSize: '14px', color: '#ffffff', fontStyle: 'bold',
   190→    }).setOrigin(0.5);
   191→
   192→    this.wpTabBtnBg = this.add.rectangle(290, TAB_Y, TAB_W, TAB_H, 0x222222)
   193→      .setStrokeStyle(1.5, 0x555555)
   194→      .setInteractive({ useHandCursor: true });
   195→    this.wpTabLabel = this.add.text(290, TAB_Y, '배경화면', {
   196→      fontSize: '14px', color: '#888888', fontStyle: 'bold',
   197→    }).setOrigin(0.5);
   198→
   199→    this.charTabBtnBg.on('pointerup', () => {
   200→      if (this.detailPanel) return;
   201→      this.switchTab('character');
   202→    });
   203→    this.wpTabBtnBg.on('pointerup', () => {
   204→      if (this.detailPanel) return;
   205→      this.switchTab('wallpaper');
   206→    });
   207→
   208→    // 구분선
   209→    this.add.rectangle(200, 80, 380, 1, 0x444444);
   210→
   211→    // 현재 선택 상태 표시
   212→    this.headerNameText = this.add.text(200, 88, `현재: ${selectedDef.name}`, {
   213→      fontSize: '13px',
   214→      color: selectedDef.gradeColor,
   215→      stroke: '#000',
   216→      strokeThickness: 3,
   217→    }).setOrigin(0.5);
   218→
   219→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   220→    this.cardsContainer = this.add.container(0, 0);
   221→
   222→    this.buildCharacterGrid();
   223→
   224→    // 스크롤 최대 범위 계산 (buildCharacterGrid 내부에서도 설정되지만 여기서도 초기화)
   225→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   226→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   227→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   228→
   229→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   230→    // this.make: display list에 추가되지 않으므로 shutdown 시 직접 정리 필요
   231→    this.maskGfx = this.make.graphics({ x: 0, y: 0 });
   232→    this.maskGfx.fillStyle(0xffffff);
   233→    this.maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   234→    this.cardsContainer.setMask(this.maskGfx.createGeometryMask());
   235→
   236→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   237→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   238→      this.hasPointerDownInScene = true;
   239→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   240→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   241→      this.pointerDownY = p.y;
   242→      this.pointerDownScrollY = this.scrollOffset;
   243→      this.hasDragged = false;
   244→    });
   245→
   246→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   247→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   248→      if (!p.isDown) return;
   249→      const dy = this.pointerDownY - p.y;
   250→      if (Math.abs(dy) > 5) {
   251→        this.hasDragged = true;
   252→        this.scrollOffset = Phaser.Math.Clamp(
   253→          this.pointerDownScrollY + dy,
   254→          0,
   255→          this.maxScrollOffset,
   256→        );
   257→        this.cardsContainer.setY(-this.scrollOffset);
   258→      }
   259→    });
   260→
   261→    this.input.on('pointerup', () => {
   262→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   263→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   264→      this.time.delayedCall(0, () => {
   265→        this.hasDragged = false;
   266→        this.hasPointerDownInScene = false;
   267→      });
   268→    });
   269→
   270→    // 마우스 휠
   271→    this.input.on(
   272→      'wheel',
   273→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   274→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   275→        this.scrollOffset = Phaser.Math.Clamp(
   276→          this.scrollOffset + deltaY * 0.5,
   277→          0,
   278→          this.maxScrollOffset,
   279→        );
   280→        this.cardsContainer.setY(-this.scrollOffset);
   281→      },
   282→    );
   283→
   284→    // ── 고정 UI ─────────────────────────────────────────────────────────
   285→    this.createBackButton();
   286→
   287→    // maskGfx는 display list 외부에 있으므로 씬 종료 시 직접 정리
   288→    this.events.once('shutdown', () => { this.maskGfx.destroy(); });
   289→  }
