   292→
   293→  private buildCharacterGrid() {
   294→    this.cardHighlights.clear();
   295→    this.coresGfx = this.add.graphics();
   296→    CHARACTERS.forEach((char, index) => {
   297→      const col = index % COLS;
   298→      const row = Math.floor(index / COLS);
   299→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   300→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   301→      this.createCharacterCard(char, x, y);
   302→    });
   303→    this.cardsContainer.add(this.coresGfx);
   304→
   305→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   306→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   307→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   308→  }
   309→
   310→  private buildWallpaperGrid() {
   311→    this.wpHighlights.clear();
   312→    // ownedWpIds: create() 초기화 + sync callback에서 직접 갱신
   313→    // selectedWpId: applyWallpaper()가 항상 동기 업데이트 → 재조회 불필요
   314→
   315→    const availableWps = WALLPAPERS.filter(w => AVAILABLE_WP_IDS.includes(w.id));
   316→    availableWps.forEach((wp, index) => {
   317→      const col = index % WP_COLS;
   318→      const row = Math.floor(index / WP_COLS);
   319→      const x = WP_GRID_LEFT + col * (WP_CARD_W + WP_GAP_X) + WP_CARD_W / 2;
   320→      const y = WP_GRID_TOP + row * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H / 2;
   321→      this.createWallpaperCard(wp, x, y);
   322→    });
   323→
   324→    const totalRows = Math.ceil(availableWps.length / WP_COLS);
   325→    const contentBottom = WP_GRID_TOP + (totalRows - 1) * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H + 10;
   326→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   327→  }
   328→
   329→  private switchTab(tab: 'character' | 'wallpaper') {
   330→    if (this.activeTab === tab) return;
   331→    this.activeTab = tab;
   332→    this.scrollOffset = 0;
   333→    this.hasDragged = false;
   334→    this.cardsContainer.setY(0);
   335→    this.updateBgForTab();
   336→
   337→    // 컨테이너 내 카드 오브젝트 전부 제거
   338→    this.cardsContainer.removeAll(true);
   339→    this.cardHighlights.clear();
   340→    this.wpHighlights.clear();
   341→
   342→    // 탭 버튼 스타일 갱신
   343→    if (tab === 'character') {
   344→      this.charTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   345→      this.charTabLabel.setColor('#ffffff');
   346→      this.wpTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   347→      this.wpTabLabel.setColor('#888888');
   348→
   349→      this.buildCharacterGrid();
   350→
   351→      // 헤더 텍스트 갱신
   352→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   353→      this.headerNameText.setText(`현재: ${def.name}`).setColor(def.gradeColor);
   354→    } else {
   355→      this.wpTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   356→      this.wpTabLabel.setColor('#ffffff');
   357→      this.charTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   358→      this.charTabLabel.setColor('#888888');
   359→
   360→      this.buildWallpaperGrid();
   361→
   362→      // 헤더 텍스트 갱신
   363→      const selWpDef = this.selectedWpId
   364→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   365→        : null;
   366→      this.headerNameText
   367→        .setText(`배경: ${selWpDef?.name ?? '기본'}`)
   368→        .setColor(this.selectedWpId ? WP_ACCENT_HEX : '#888888');
   369→    }
   370→  }
