   372→  /** 현재 탭에 맞게 배경 이미지 업데이트 */
   373→  private updateBgForTab() {
   374→    if (this.activeTab === 'character') {
   375→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   376→      this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   377→    } else {
   378→      const wpDef = this.selectedWpId
   379→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   380→        : null;
   381→      if (wpDef && this.textures.exists(wpDef.bgKey)) {
   382→        this.bgImage.setTexture(wpDef.bgKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   383→      } else {
   384→        // 선택 배경 없음 → 캐릭터 일러스트를 어둡게 처리
   385→        const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   386→        this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(0.2);
   387→      }
   388→    }
   389→  }
