   391→  /** 서버 동기화 후 현재 탭을 내용 갱신 */
   392→  private rebuildGrid() {
   393→    this.cardsContainer.removeAll(true);
   394→    this.cardHighlights.clear();
   395→    this.wpHighlights.clear();
   396→    if (this.activeTab === 'character') {
   397→      this.buildCharacterGrid();
   398→    } else {
   399→      this.buildWallpaperGrid();
   400→    }
   401→  }
