   404→
   405→  private createWallpaperCard(wp: BackgroundDef, x: number, y: number) {
   406→    const isOwned = this.ownedWpIds.includes(wp.id);
   407→    const isSelected = this.selectedWpId === wp.id;
   408→
   409→    // 카드 배경
   410→    const cardBg = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0x1a1a2e);
   411→    cardBg.setStrokeStyle(2, isOwned ? WP_ACCENT_INT : 0x333333);
   412→    this.cardsContainer.add(cardBg);
   413→
   414→    // 선택 하이라이트 (흰 테두리)
   415→    const highlight = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0, 0);
   416→    highlight.setStrokeStyle(3, 0xffffff);
   417→    highlight.setVisible(isSelected);
   418→    this.wpHighlights.set(wp.id, highlight);
   419→    this.cardsContainer.add(highlight);
   420→
   421→    // 세로 이미지 (bgKey) — 카드 상단을 채우는 portrait 썸네일
   422→    if (this.textures.exists(wp.bgKey)) {
   423→      const thumb = this.add.image(x, y - 11, wp.bgKey)
   424→        .setDisplaySize(WP_CARD_W - 4, WP_CARD_H - 22);
   425→      if (!isOwned) { thumb.setTint(0x000000); thumb.setAlpha(0.5); }
   426→      this.cardsContainer.add(thumb);
   427→    }
   428→
   429→    // 미보유 자물쇠
   430→    if (!isOwned) {
   431→      const lock = this.add.text(x, y - 8, '🔒', { fontSize: '20px' }).setOrigin(0.5);
   432→      this.cardsContainer.add(lock);
   433→    }
   434→
   435→    // WP 배지 (우상단) — 기본 배경은 '기본', 가챠 배경은 'WP'
   436→    const isDefault = (DEFAULT_WP_IDS as readonly string[]).includes(wp.id);
   437→    const badgeText  = isDefault ? '기본' : 'WP';
   438→    const badgeColor = isDefault ? '#aaaaaa' : WP_ACCENT_HEX;
   439→    const badge = this.add.text(x + WP_CARD_W / 2 - 2, y - WP_CARD_H / 2 + 2, badgeText, {
   440→      fontSize: '9px', color: badgeColor, fontStyle: 'bold',
   441→      backgroundColor: '#000000cc', padding: { x: 3, y: 1 },
   442→    }).setOrigin(1, 0);
   443→    this.cardsContainer.add(badge);
   444→
   445→    // 하단 반투명 바 + 이름
   446→    const barY = y + WP_CARD_H / 2 - 11;
   447→    const bar = this.add.rectangle(x, barY, WP_CARD_W, 22, 0x000000, 0.75);
   448→    this.cardsContainer.add(bar);
   449→    const nameText = this.add.text(x, barY, wp.name, {
   450→      fontSize: '11px',
   451→      color: isOwned ? WP_ACCENT_HEX : '#444444',
   452→      fontStyle: 'bold',
   453→    }).setOrigin(0.5);
   454→    this.cardsContainer.add(nameText);
   455→
   456→    // 클릭 이벤트
   457→    cardBg.setInteractive({ useHandCursor: isOwned });
   458→    if (isOwned) {
   459→      cardBg.on('pointerover', () => cardBg.setFillStyle(0x252540));
   460→      cardBg.on('pointerout',  () => cardBg.setFillStyle(0x1a1a2e));
   461→    }
   462→    cardBg.on('pointerup', () => {
   463→      if (!this.hasDragged && this.hasPointerDownInScene) this.showWallpaperDetail(wp);
   464→    });
   465→  }
