   575→  private applyWallpaper(id: string | null) {
   576→    setSelectedWallpaper(id);
   577→    this.selectedWpId = id;
   578→
   579→    // 하이라이트 갱신
   580→    this.wpHighlights.forEach((rect, wpId) => {
   581→      rect.setVisible(wpId === id);
   582→    });
   583→
   584→    // 헤더 텍스트 갱신
   585→    const def = id ? WALLPAPERS.find(w => w.id === id) : null;
   586→    this.headerNameText
   587→      .setText(`배경: ${def?.name ?? '기본'}`)
   588→      .setColor(id ? WP_ACCENT_HEX : '#888888');
   589→
   590→    // 배경 이미지 즉시 반영
   591→    this.updateBgForTab();
   592→
   593→    this.hideCharacterDetail();
   594→  }
