   596→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   597→    const isOwned = this.ownedIds.includes(char.id);
   598→    const isSelected = this.selectedId === char.id;
   599→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   600→
   601→    // 카드 배경
   602→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   603→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   604→    this.cardsContainer.add(cardBg);
   605→
   606→    // 선택 하이라이트
   607→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   608→    highlight.setStrokeStyle(3, 0xffffff);
   609→    highlight.setVisible(isSelected);
   610→    this.cardHighlights.set(char.id, highlight);
   611→    this.cardsContainer.add(highlight);
   612→
   613→    // 캐릭터 이미지
   614→    const img = this.add.image(x, y - 12, char.imageKey);
   615→    img.setDisplaySize(58, 85);
   616→    this.cardsContainer.add(img);
   617→
   618→    if (!isOwned) {
   619→      img.setTint(0x000000);
   620→      img.setAlpha(0.6);
   621→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   622→      this.cardsContainer.add(lock);
   623→    }
   624→
   625→    // 등급 배지
   626→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   627→      fontSize: '9px',
   628→      color: char.gradeColor,
   629→      fontStyle: 'bold',
   630→      backgroundColor: '#000000cc',
   631→      padding: { x: 3, y: 1 },
   632→    }).setOrigin(1, 0);
   633→    this.cardsContainer.add(badge);
   634→
   635→    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
   636→    if (isOwned && char.grade !== '등급외') {
   637→      const dupCount   = getDuplicateCount(char.id);
   638→      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
   639→      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;
   640→
   641→      for (let i = 0; i < CORE_COUNT; i++) {
   642→        const cx = x + (i - 2) * CORE_GAP;
   643→        if (i < awakeLevel) {
   644→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
   645→          this.coresGfx.fillStyle(gradeColorInt, 0.25);
   646→          this.coresGfx.fillCircle(cx, coreY, CORE_GLOW_RADIUS);
   647→          this.coresGfx.fillStyle(gradeColorInt, 1);
   648→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   649→          this.coresGfx.fillStyle(0xffffff, 0.55);
   650→          this.coresGfx.fillCircle(cx - 1, coreY - 1, CORE_HIGHLIGHT_R);
   651→        } else {
   652→          // 빈 코어: 어두운 원 + 얇은 테두리
   653→          this.coresGfx.fillStyle(0x111111, 1);
   654→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   655→          this.coresGfx.lineStyle(1, gradeColorInt, 0.35);
   656→          this.coresGfx.strokeCircle(cx, coreY, CORE_INNER_RADIUS);
   657→        }
   658→      }
   659→    }
   660→
   661→    // 캐릭터 이름
   662→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   663→      fontSize: '12px',
   664→      color: isOwned ? '#ffffff' : '#555555',
   665→      fontStyle: 'bold',
   666→    }).setOrigin(0.5);
   667→    this.cardsContainer.add(nameText);
   668→
   669→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   670→    cardBg.setInteractive({ useHandCursor: isOwned });
   671→
   672→    if (isOwned) {
   673→      cardBg.on('pointerover', () => {
   674→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   675→      });
   676→      cardBg.on('pointerout', () => {
   677→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   678→      });
   679→    }
   680→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
   681→    cardBg.on('pointerup', () => {
   682→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
   683→    });
   684→  }
