   814→    if (hasVideo && videoObj) {
   815→      // 일러스트 탭 → 비디오 재생 (가챠와 동일한 fitVideo 방식)
   816→      // active 체크: ✕ 탭 시 패널 파괴 직후 이 핸들러가 동시에 발화하는 경우 방지
   817→      const startVideo = () => {
   818→        if (!illust.active || !videoObj?.active) return;
   819→        videoObj!.setVisible(true);
   820→        videoObj!.play(false);
   821→        this.fitVideoToPanel(videoObj!);
   822→        // 비디오 'play' 이벤트 = 실제 재생 시작 시점 → 그때 일러스트 숨김
   823→        // (즉시 숨기면 첫 프레임 렌더 전 갭에 카드 목록이 비침)
   824→        videoObj!.once('play', () => {
