   827→      };
   828→      illust.setInteractive({ useHandCursor: true });
   829→      illust.on('pointerup', startVideo);
   830→
   831→      // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
   832→      const stopVideo = () => {
   833→        videoObj!.stop();
   834→        videoObj!.setVisible(false);
   835→        illust.setVisible(true);
   836→      };
   837→      videoObj.setInteractive({ useHandCursor: true });
   838→      videoObj.on('pointerup', stopVideo);
   839→      videoObj.on('complete', stopVideo);
   840→    }
   841→  }
