   843→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   844→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   845→    const W = 400, H = 600;
   846→    vid.setDisplaySize(W, H);
   847→
   848→    const applyContain = () => {
   849→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   850→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   851→      const nw = el?.videoWidth  || 0;
   852→      const nh = el?.videoHeight || 0;
   853→      if (nw > 0 && nh > 0) {
   854→        const scale = Math.max(W / nw, H / nh);
   855→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   856→      }
   857→    };
   858→
   859→    vid.once('play', applyContain);
   860→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   861→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   862→  }
   863→
   864→  private hideCharacterDetail(): void {
   865→    // fitVideoToPanel의 pending 타이머 취소
   866→    for (const t of this.fitVideoTimers) t.remove();
   867→    this.fitVideoTimers = [];
   868→
   869→    // 비디오 명시 정지 및 HTMLVideoElement src 해제
   870→    if (this.detailVideo) {
   871→      this.detailVideo.stop();
   872→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   873→      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
   874→      if (el) { el.src = ''; }
   875→      this.detailVideo = null;
   876→    }
   877→
   878→    this.hideInfoPanel();
   879→    this.detailPanel?.destroy();
   880→    this.detailPanel = null;
   881→  }
